## --- Test creating and allocating a PlanarZirconHe

    crystalradius = 29.26
    U = 462.98
    Th = 177.76
    zircon = PlanarZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps))
    @test isa(zircon, PlanarZirconHe)
    show(zircon)
    println()
    display(zircon)

    @test zircon.agesteps == reverse(tsteps)
    @test zircon.r238U ≈ fill(1.1714561176470587e18, 29)
    @test zircon.r235U ≈ fill(8.608533548562195e15, 29)
    @test zircon.r232Th ≈ fill(4.614097931034483e17, 29)
    @test zircon.r147Sm ≈ fill(0.0, 29)
    @test zircon.redges == 0:dr:crystalradius
