## --- Test integrated age program for PlanarZirconHe

    dm = ZRDAAM(
        Ea_z = 165.0,       # kJ/mol
        D0_z = 193188.0,    # cm^2/sec
        Ea_N17 = 71.0,      # kJ/mol
        D0_N17 = 3.4E-3,    # 6.367e-3 cm^2/sec
        rmin=0.0,           # unitless
    )
    pr, Teq = Thermochron.anneal(tsteps, Tsteps, dm)
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 624.2942106832655
    end

    crystalradius = 35.
    U = 1107.
    Th = 351.
    zircon = PlanarZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps))
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 369.44055439790804
    end

    crystalradius = 135.
    U = 1738.
    Th = 1171.
    zircon = PlanarZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps))
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 34.781174338354376
    end

    crystalradius = 135.
    U = 500.
    Th = 400.
    zircon = PlanarZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps))
    mul!(zircon.annealeddamage, pr, zircon.alphadamage)
    for _ in 1:4 # Re-run to ensure internal state does not change
        @test modelage(zircon,Tsteps,dm) ≈ 824.1253560712642
    end

## --- Test creating and allocating a ZirconHe

    crystalradius = 29.26
    U = 462.98
    Th = 177.76
    zircon = ZirconHe(r=crystalradius,dr=dr,U238=U,Th232=Th,agesteps=reverse(tsteps), volumeweighting=:spherical)
    @test isa(zircon, ZirconHe)
    show(zircon)
    println()
    display(zircon)

